mapper.select:
select *,clazz.name clazzName from student left join clazz on clazz.id=clazz_id

    student.name like concat('%',#{name},'%')
    and degree <= #{degree}
    and clazz_id=#{clazzId}

select (case

    when clazz_id=#{clazz.id} then #{clazz.name}
)as clazzName,
count(*) as data
from student
group by clazz_id
order by data;
